let myComp = new_definition
  `myComp (g:B->C) (f:A->B) = (\x:A. g (f x))`;;

let myId = new_definition
  `myId = (\x:A. x)`;;

let comp_assoc = prove
  (`!h g f. myComp h (myComp g f) = myComp (myComp h g) f`,
   REWRITE_TAC[myComp]);;

let comp_id_l = prove
  (`!f:A->B. myComp myId f = f`,
   REWRITE_TAC[myComp; myId; FUN_EQ_THM] THEN BETA_TAC THEN REWRITE_TAC[]);;

let comp_id_r = prove
  (`!f:A->B. myComp f myId = f`,
   REWRITE_TAC[myComp; myId; FUN_EQ_THM] THEN BETA_TAC THEN REWRITE_TAC[]);;

let commute = new_definition
  `commute (f:A->A) (g:A->A) <=> myComp f g = myComp g f`;;

let commute_symm = prove
  (`!f g. commute f g ==> commute g f`,
   REWRITE_TAC[commute] THEN MESON_TAC[]);;

let commute_with_id_l = prove
  (`!f:A->A. commute f myId`,
   REWRITE_TAC[commute] THEN
   REWRITE_TAC[comp_id_l; comp_id_r]);;

let commute_with_id_r = prove
  (`!f:A->A. commute myId f`,
   REWRITE_TAC[commute] THEN
   REWRITE_TAC[comp_id_l; comp_id_r]);;

let commute_refl = prove
  (`!f:A->A. commute f f`,
   REWRITE_TAC[commute]);;

let commute_congr = prove
  (`!f1 f2 g1 g2:A->A.
      f1 = f2 ==> g1 = g2 ==> commute f1 g1 ==> commute f2 g2`,
   REWRITE_TAC[commute] THEN MESON_TAC[]);;

let commute_transport_left_id = prove
  (`!f g:A->A. commute f g ==> commute (myComp myId f) g`,
   REWRITE_TAC[commute] THEN
   REWRITE_TAC[comp_id_l]);;

let commute_transport_right_id = prove
  (`!f g:A->A. commute f g ==> commute f (myComp myId g)`,
   REWRITE_TAC[commute] THEN
   REWRITE_TAC[comp_id_l]);;

(*
  inner_product.v — Self-contained inner product space lemmas in Coq

  We axiomatize a scalar field R, a vector space V over R, and a symmetric
  bilinear form ⟪·,·⟫ : V → V → R. We derive Pythagoras and the
  parallelogram identity in algebraic form.
*)

Class Field := {
  R0    : Type;
  zeroR : R0;
  oneR  : R0;
  addR  : R0 -> R0 -> R0;
  mulR  : R0 -> R0 -> R0;
  oppR  : R0 -> R0;

  addR_comm  : forall x y, addR x y = addR y x;
  addR_assoc : forall x y z, addR (addR x y) z = addR x (addR y z);
  addR_zero  : forall x, addR x zeroR = x;
  zeroR_add  : forall x, addR zeroR x = x;
  addR_opp   : forall x, addR x (oppR x) = zeroR;

  mulR_comm  : forall x y, mulR x y = mulR y x;
  mulR_assoc : forall x y z, mulR (mulR x y) z = mulR x (mulR y z);
  mulR_one   : forall x, mulR x oneR = x;
  distR_l    : forall x y z, mulR x (addR y z) = addR (mulR x y) (mulR x z);

  oppR_add   : forall x y, oppR (addR x y) = addR (oppR x) (oppR y);
  mulR_opp_one : forall x, mulR (oppR oneR) x = oppR x;
  oppR_opp : forall x, oppR (oppR x) = x
}.

Section Linear.
  Context {F : Field}.

  Infix "+R" := addR (at level 65).
  Infix "*R" := mulR (at level 70).
  Notation "-R x" := (oppR x) (at level 100).

  Class VSpace := {
    V0     : Type;
    zeroV  : V0;
    addV   : V0 -> V0 -> V0;
    oppV   : V0 -> V0;
    smul   : R0 -> V0 -> V0;

    addV_comm  : forall u v, addV u v = addV v u;
    addV_assoc : forall u v w, addV (addV u v) w = addV u (addV v w);
    addV_zero  : forall u, addV u zeroV = u;
    addV_opp   : forall u, addV u (oppV u) = zeroV;

    smul_addV  : forall a u v, smul a (addV u v) = addV (smul a u) (smul a v);
    addR_smul  : forall a b u, smul (a +R b) u = addV (smul a u) (smul b u);
    mul_smul   : forall a b u, smul (a *R b) u = smul a (smul b u);
    one_smul   : forall u, smul oneR u = u;
    smul_zeroV : forall a, smul a zeroV = zeroV;
    opp_smul_one : forall u, oppV u = smul (oppR oneR) u
  }.

  Infix "+V" := addV (at level 65).
  Notation "-V x" := (oppV x) (at level 100).
  Notation "a •V x" := (smul a x) (at level 70).
  Definition subV {VS : VSpace} (u v : V0) := addV u (oppV v).
  Infix "-V" := subV (at level 65).

  Class Inner `{VS : VSpace} := {
    ip : V0 -> V0 -> R0;

    lin_left_add  : forall u v w, (ip (u +V v) w) = ((ip u w) +R (ip v w));
    lin_left_smul : forall a u v, (ip (a •V u) v) = (a *R (ip u v));

    lin_right_add  : forall u v w, (ip u (v +V w)) = ((ip u v) +R (ip u w));
    lin_right_smul : forall a u v, (ip u (a •V v)) = (a *R (ip u v));

    symm : forall u v, ip u v = ip v u
  }.

    Context `{VS : VSpace} `{IN : Inner}.

    Notation "⟪ x , y ⟫" := (ip x y) (at level 80).

    Lemma ip_neg_left : forall u v, ⟪-V u, v⟫ = -R ⟪u, v⟫.
    Proof.
      intros u v.
      rewrite opp_smul_one.
      rewrite lin_left_smul.
      now rewrite mulR_opp_one.
    Qed.

    Lemma ip_neg_right : forall u v, ⟪u, -V v⟫ = -R ⟪u, v⟫.
    Proof.
      intros u v.
      rewrite opp_smul_one.
      rewrite lin_right_smul.
      now rewrite mulR_opp_one.
    Qed.

    Lemma ip_add_add : forall u v,
      ⟪u +V v, u +V v⟫ = ((⟪u,u⟫ +R ⟪v,u⟫) +R (⟪u,v⟫ +R ⟪v,v⟫)).
    Proof.
      intros u v.
      pose proof (lin_right_add (u +V v) u v) as H.
      pose proof (lin_left_add u v u) as H1.
      pose proof (lin_left_add u v v) as H2.
      rewrite H1, H2 in H.
      exact H.
    Qed.

    Lemma ip_sub_sub : forall u v,
      ⟪u -V v, u -V v⟫ = ((⟪u,u⟫ +R (-R ⟪v,u⟫)) +R ((-R ⟪u,v⟫) +R ⟪v,v⟫)).
    Proof.
      intros u v.
      unfold subV in *.
      pose proof (lin_right_add (addV u (oppV v)) u (oppV v)) as H.
      pose proof (lin_left_add u (oppV v) u) as H1.
      pose proof (lin_left_add u (oppV v) (oppV v)) as H2.
      rewrite H1, H2 in H.
      (* Simplify the mixed terms *)
      rewrite (ip_neg_left v u) in H.
      rewrite (ip_neg_right u v) in H.
      (* Simplify ⟪-v, -v⟫ to ⟪v,v⟫ using two negation lemmas *)
      rewrite (ip_neg_right (oppV v) v) in H.
      rewrite (ip_neg_left v v) in H.
      rewrite oppR_opp in H.
      exact H.
    Qed.

    Lemma pythagoras : forall u v,
      ⟪u,v⟫ = zeroR ->
      ⟪u +V v, u +V v⟫ = (⟪u,u⟫ +R ⟪v,v⟫).
    Proof.
      intros u v Huv.
      pose proof (ip_add_add u v) as H.
      assert (Hvu : ⟪v,u⟫ = zeroR) by (now rewrite <- symm).
      rewrite Huv, Hvu in H.
      rewrite addR_zero in H.
      rewrite zeroR_add in H.
      exact H.
    Qed.

    Lemma parallelogram : forall u v,
      (⟪u +V v, u +V v⟫ +R ⟪u -V v, u -V v⟫)
        = (((⟪u,u⟫ +R ⟪v,u⟫) +R (⟪u,v⟫ +R ⟪v,v⟫))
           +R ((⟪u,u⟫ +R (-R ⟪v,u⟫)) +R ((-R ⟪u,v⟫) +R ⟪v,v⟫))).
    Proof.
      intros u v.
      pose proof (ip_add_add u v) as H1.
      pose proof (ip_sub_sub u v) as H2.
      rewrite H1, H2.
      reflexivity.
    Qed.

End Linear.

Class AbsField := {
  R0   : Type;
  zero : R0;
  one  : R0;
  add  : R0 -> R0 -> R0;
  mul  : R0 -> R0 -> R0;
  opp  : R0 -> R0;
  abs  : R0 -> R0;
  leR  : R0 -> R0 -> Prop;
  ltR  : R0 -> R0 -> Prop;


  N0       : Type;
  Nle      : N0 -> N0 -> Prop;
  Nmax     : N0 -> N0 -> N0;
  Nle_max_l : forall x y, Nle x (Nmax x y);
  Nle_max_r : forall x y, Nle y (Nmax x y);

  add_comm  : forall x y, add x y = add y x;
  add_assoc : forall x y z, add (add x y) z = add x (add y z);
  add_zero  : forall x, add x zero = x;
  add_opp   : forall x, add x (opp x) = zero;
  mul_comm  : forall x y, mul x y = mul y x;
  mul_assoc : forall x y z, mul (mul x y) z = mul x (mul y z);
  mul_one   : forall x, mul x one = x;

  le_refl   : forall x, leR x x;
  le_trans  : forall x y z, leR x y -> leR y z -> leR x z;
  add_le_add : forall a b c d, leR a b -> leR c d -> leR (add a c) (add b d);

  abs_nonneg : forall x, leR zero (abs x);
  abs_triangle : forall x y, leR (abs (add x y)) (add (abs x) (abs y));
  abs_opp : forall x, abs (opp x) = abs x;
  abs_sub_symm : forall x y, abs (add x (opp y)) = abs (add y (opp x));
  sub_decomp : forall x y z, add x (opp z) = add (add x (opp y)) (add y (opp z));
  sub_eq_zero : forall x y, add x (opp y) = zero -> x = y;


  eq_of_forall_eps2 : forall x, (forall eps, ltR zero eps -> leR (abs x) (add eps eps)) -> x = zero
}.

Section Limits.
  Context {A : AbsField}.

  Infix "+R" := add (at level 65).
  Notation "-R x" := (opp x) (at level 100).

  Definition sub (x y : R0) : R0 := add x (opp y).

  Definition limit (u : N0 -> R0) (l : R0) : Prop :=
    forall eps, ltR zero eps -> exists N, forall n, Nle N n -> leR (abs (sub (u n) l)) eps.

  Lemma abs_sub_triangle (x y z : R0) :
    leR (abs (sub x z)) (add (abs (sub x y)) (abs (sub y z))).
  Proof.
    unfold sub.
    rewrite (sub_decomp x y z).
    apply abs_triangle.
  Qed.

  Theorem limit_unique (u : N0 -> R0) (l m : R0) :
    limit u l -> limit u m -> l = m.
  Proof.
    intros Hl Hm.
    assert (Hbound: forall eps, ltR zero eps -> leR (abs (sub l m)) (add eps eps)).
    { intros eps Heps.
      destruct (Hl eps Heps) as [N1 HN1].
      destruct (Hm eps Heps) as [N2 HN2].
      set (N := Nmax N1 N2).
      assert (H1u: leR (abs (sub (u N) l)) eps).
      { apply HN1. apply Nle_max_l. }
      assert (H1: leR (abs (sub l (u N))) eps).
      { unfold sub in H1u. rewrite abs_sub_symm in H1u. fold sub in H1u. exact H1u. }
      assert (H2: leR (abs (sub (u N) m)) eps).
      { apply HN2. apply Nle_max_r. }
      assert (Htri: leR (abs (sub l m)) (add (abs (sub l (u N))) (abs (sub (u N) m)))) by apply abs_sub_triangle.
      eapply le_trans; [exact Htri|].
      apply add_le_add; [exact H1|exact H2].
    }
    assert (Hz: sub l m = zero).
    { apply eq_of_forall_eps2. exact Hbound. }
    unfold sub in Hz.
    now apply sub_eq_zero in Hz.
  Qed.

End Limits.

Class Field := {
  R0    : Type;
  zeroR : R0;
  oneR  : R0;
  addR  : R0 -> R0 -> R0;
  mulR  : R0 -> R0 -> R0;
  oppR  : R0 -> R0;
  addR_comm  : forall x y, addR x y = addR y x;
  addR_assoc : forall x y z, addR (addR x y) z = addR x (addR y z);
  addR_zero  : forall x, addR x zeroR = x;
  addR_opp   : forall x, addR x (oppR x) = zeroR;
  mulR_comm  : forall x y, mulR x y = mulR y x;
  mulR_assoc : forall x y z, mulR (mulR x y) z = mulR x (mulR y z);
  mulR_one   : forall x, mulR x oneR = x;
  distR_l    : forall a x y, mulR a (addR x y) = addR (mulR a x) (mulR a y)
}.

Section Lin.
  Context {F : Field}.
  Infix "+R" := addR (at level 65).
  Infix "*R" := mulR (at level 70).
  Notation "-R x" := (oppR x) (at level 100).

  Class VSpace := {
    V0    : Type;
    zeroV : V0;
    addV  : V0 -> V0 -> V0;
    oppV  : V0 -> V0;
    smul  : R0 -> V0 -> V0;
    addV_comm  : forall u v, addV u v = addV v u;
    addV_assoc : forall u v w, addV (addV u v) w = addV u (addV v w);
    addV_zero  : forall u, addV u zeroV = u;
    addV_opp   : forall u, addV u (oppV u) = zeroV;
    smul_addV  : forall a u v, smul a (addV u v) = addV (smul a u) (smul a v);
    addR_smul  : forall a b u, smul (a +R b) u = addV (smul a u) (smul b u);
    mul_smul   : forall a b u, smul (a *R b) u = smul a (smul b u);
    one_smul   : forall u, smul oneR u = u;
    smul_zeroV : forall a, smul a zeroV = zeroV
  }.

  Infix "+V" := addV (at level 65).
  Notation "a •V x" := (smul a x) (at level 70).

  Record Lin `{VS1 : VSpace} `{VS2 : VSpace} := {
    toFun    : V0 -> V0;
    map_add  : forall u v, toFun (u +V v) = addV (toFun u) (toFun v);
    map_smul : forall a u, toFun (a •V u) = smul a (toFun u)
  }.

  Definition ker `{VS1 : VSpace} `{VS2 : VSpace} (L : Lin) : V0 -> Prop :=
    fun x => toFun L x = zeroV.
  Definition im  `{VS1 : VSpace} `{VS2 : VSpace} (L : Lin) : V0 -> Prop :=
    fun y => exists x, toFun L x = y.

  Lemma ker_add `{VS1 : VSpace} `{VS2 : VSpace}
    (L : Lin) (x y : V0) :
    ker L x -> ker L y -> ker L (x +V y).
  Proof.
    intros hx hy.
    unfold ker in *.
    rewrite map_add.
    rewrite hx, hy.
    now rewrite addV_zero.
  Qed.

  Lemma ker_smul `{VS1 : VSpace} `{VS2 : VSpace}
    (L : Lin) (a : R0) (x : V0) : ker L x -> ker L (a •V x).
  Proof.
    intros hx; unfold ker in *.
    now rewrite map_smul, hx, smul_zeroV.
  Qed.

  Lemma im_add `{VS1 : VSpace} `{VS2 : VSpace}
    (L : Lin) (y z : V0) :
    im L y -> im L z -> im L (y +V z).
  Proof.
    intros [x Hx] [x' Hx']; subst y z.
    exists (x +V x').
    now rewrite map_add.
  Qed.

  Lemma im_smul `{VS1 : VSpace} `{VS2 : VSpace}
    (L : Lin) (a : R0) (y : V0) :
    im L y -> im L (a •V y).
  Proof.
    intros [x Hx]; subst y.
    exists (a •V x); now rewrite map_smul.
  Qed.

End Lin.

let sUnion = new_definition
  `sUnion (A:'a->bool) (B:'a->bool) = \x. A x \/ B x`;;

let sInter = new_definition
  `sInter (A:'a->bool) (B:'a->bool) = \x. A x /\ B x`;;

let sCompl = new_definition
  `sCompl (A:'a->bool) = \x. ~A x`;;

let inter_distrib_left = prove
  (`!A B C x. sInter A (sUnion B C) x <=> sUnion (sInter A B) (sInter A C) x`,
  REWRITE_TAC[sUnion; sInter] THEN MESON_TAC[]);;

let inter_distrib_right = prove
  (`!A B C x. sInter (sUnion A B) C x <=> sUnion (sInter A C) (sInter B C) x`,
  REWRITE_TAC[sUnion; sInter] THEN MESON_TAC[]);;

let de_morgan_union = prove
  (`!A B x. sCompl (sUnion A B) x <=> sInter (sCompl A) (sCompl B) x`,
  REWRITE_TAC[sUnion; sInter; sCompl] THEN MESON_TAC[]);;

let de_morgan_inter = prove
  (`!A B x. sCompl (sInter A B) x <=> sUnion (sCompl A) (sCompl B) x`,
  REWRITE_TAC[sUnion; sInter; sCompl] THEN MESON_TAC[]);;

